function renderScopeSelectionReview(){
  const selection=state.productionScopeSelection,summary=$('#scopeSelectionSummary'),validation=$('#scopeSelectionValidation'),error=$('#scopeSelectionError'),reviewButton=$('#reviewProductionScope'),book=scopeSelectedBook();
  if(!summary||!validation)return;
  if(selection.singleChapter&&selection.fromChapter)selection.toChapter=selection.fromChapter;
  const from=Number(selection.fromChapter)||0,to=Number(selection.toChapter)||0,chapterCount=Number(book?.chapter_count||0);
  const fromInput=$('#scopeFromChapter'),toInput=$('#scopeToChapter'),singleInput=$('#scopeSingleChapter'),skipInput=$('#scopeSkipCompleted');
  if(fromInput&&document.activeElement!==fromInput)fromInput.value=from||'';
  if(toInput&&document.activeElement!==toInput)toInput.value=to||'';
  if(singleInput)singleInput.checked=!!selection.singleChapter;
  if(skipInput)skipInput.checked=!!selection.skipCompleted;
  let message='';
  if(!book)message='Hãy chọn sách trước.';
  else if(!from||!to)message='Hãy nhập chương bắt đầu và chương kết thúc.';
  else if(from>to)message=`Chương ${from} đang lớn hơn Chương ${to}. Hãy đổi lại thứ tự.`;
  else if(from<1||to>chapterCount)message=`Phạm vi phải nằm trong 1-${chapterCount} của sách này.`;
  validation.textContent=message;validation.classList.toggle('hidden',!message);
  if(error){error.textContent=selection.error?.message||'';error.classList.toggle('hidden',!selection.error?.message)}
  if(reviewButton){reviewButton.disabled=!!message||!!selection.review?.loading;reviewButton.textContent=selection.review?.loading?'Đang kiểm tra…':'Kiểm tra phạm vi'}
  const total=from&&to&&from<=to?to-from+1:0,complete=Number(selection.review?.result?.summary?.complete||0),inspect=Math.max(0,total-(selection.skipCompleted?complete:0));
  summary.replaceChildren();const strong=document.createElement('strong'),span=document.createElement('span');strong.textContent=book&&total?`${book.title} · Chương ${from}${from===to?'':`-${to}`}`:'Chưa đủ phạm vi';span.textContent=total?`${total} chương${selection.skipCompleted?` · ${inspect} chương sẽ được xử lý`:''}`:'Chọn sách và nhập số chương để kiểm tra.';summary.append(strong,span);
}
