api=async function(url,options={}){const method=String(options.method||'GET').toUpperCase(),readiness=state.productionPrepare?.readiness;if(method==='POST'&&readiness?.runtime_mode==='PRODUCTION'){if(/^\/api\/jobs(?:\/prepare)?$/.test(url))throw new Error('Legacy job preparation khong kha dung trong Production mode.');if(/^\/api\/jobs\/\d+\/start$/.test(url)&&!readiness?.start_render_available)throw new Error('START_RENDER chua duoc operator mo cho runtime nay.')}const response=await fetch(url,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});let payload;try{payload=await response.json()}catch{payload={detail:'Response error'}}if(!response.ok){const error=new Error(friendlyApiError(payload,response.status));error.details=payload;error.status=response.status;throw error}return payload};
