function renderProductionFlow(model,context){
  if(!state.dialog?.chapter)return;
  const vm=currentProductionViewModel();
  const canonicalStepId=productionCurrentFlowStep(vm);
  ensureProductionFlowSelection(state.dialog.chapter.id,canonicalStepId);
  selectProductionFlowStep(canonicalStepId,{auto:true});
  const recommended=model.steps.find(step=>step.id===canonicalStepId)||model.steps.find(step=>step.id===model.currentStepId)||model.steps[0];
  const selected=recommended;
  $('#productionFlowCurrentStep').textContent=productionStepTitle(selected.id);
  $('#productionFlowStepper').innerHTML=model.steps.map(step=>{
    const active=step.id===selected.id;
    const locked=!active;
    return `<button class="flow-step ${active?'current selected':''} ${step.complete?'complete':''} ${step.blocker?'blocked':''}" data-flow-step="${step.id}" ${locked?'disabled aria-disabled="true"':''}><span>Bước ${step.number}</span><strong>${esc(step.title)}</strong><small>${locked?'Đã tóm tắt / đang khóa':esc(step.label)}</small></button>`;
  }).join('');
  document.querySelectorAll('[data-flow-step]').forEach(button=>button.onclick=()=>{if(button.disabled)return;focusProductionFlowStep(selected.id,{exitToChapterList:selected.id==='select-chapter'})});
  $('#castingRecommendedActionTitle').textContent=productionStepTitle(selected.id);
  $('#castingRecommendedActionBody').textContent=vm.explanation||selected.purpose;
  $('#castingRecommendedActionState').textContent=vm.conceptualState;
  $('#productionFlowStepTitle').textContent=productionStepTitle(selected.id);
  $('#productionFlowStepStatus').textContent=selected.label;
  $('#productionFlowStepPurpose').textContent=selected.purpose;
  $('#productionFlowStepInputs').textContent=selected.inputs;
  $('#productionFlowStepAfter').textContent=selected.after;
  const selectedMessage=vm.blockerReason||selected.blocker||selected.note||'';
  $('#productionFlowBlockedReason').textContent=selectedMessage;
  $('#productionFlowBlockedReason').classList.toggle('hidden',!selectedMessage);
  renderFlowStepSections(model,context);
  applyProductionStageIsolation(vm);
  $('#productionFlowBack').disabled=true;
  $('#productionFlowBack').onclick=null;
  $('#productionFlowContinue').textContent=productionStepActionLabel(selected.id);
  $('#productionFlowContinue').onclick=()=>focusProductionFlowStep(selected.id,{exitToChapterList:selected.id==='select-chapter'});
  $('#productionFlowNext').disabled=true;
  $('#productionFlowNext').classList.remove('primary');
  $('#productionFlowNext').classList.add('secondary');
  $('#productionFlowNext').textContent='Các bước khác đang khóa';
  $('#productionFlowNext').onclick=null;
}
async function loadChapters(){if(!state.book)return;const q=encodeURIComponent($('#chapterQuery').value.trim());const data=await api(`/api/books/${state.book.id}/chapters?offset=${state.page*state.pageSize}&limit=${state.pageSize}&query=${q}`);state.total=data.total;$('#chapterList').innerHTML=data.items.map(c=>{const status=chapterStatusSummary(c),casting=castingStatusSummary(c);return `<div class="chapter-row" data-id="${c.id}"><span class="chapter-number">${c.chapter_number}</span><span class="chapter-title-wrap"><span class="chapter-title">${esc(c.title)}</span>${status.meta?`<span class="chapter-title-meta">${esc(status.meta)}</span>`:''}</span><span class="chapter-casting-meta">${casting?`<span class="status-dot ${casting.className}">${casting.label}</span>`:''}<span class="status-dot ${status.className}">${status.label}</span></span><button class="secondary chapter-action" data-open-casting="${c.id}">Mở quy trình sản xuất</button></div>`}).join('');document.querySelectorAll('.chapter-row').forEach(el=>el.onclick=event=>{if(event.target.closest('[data-open-casting]'))return;openChapter(+el.dataset.id)});document.querySelectorAll('[data-open-casting]').forEach(el=>el.onclick=event=>{event.stopPropagation();openChapter(+el.dataset.openCasting,{initialTab:'casting'})});$('#pageInfo').textContent=`${state.page*state.pageSize+1}-${Math.min((state.page+1)*state.pageSize,state.total)} / ${state.total}`;$('#prevPage').disabled=state.page===0;$('#nextPage').disabled=(state.page+1)*state.pageSize>=state.total}
async function openChapter(id,options={}){
  try{
    state.dialog=await api(`/api/chapters/${id}`);
    state.casting=state.casting?.chapter?.id===id?state.casting:null;
    if(!state.book||Number(state.book.id)!==Number(state.dialog.chapter.book_id))state.book=state.books.find(b=>Number(b.id)===Number(state.dialog.chapter.book_id))||state.book;
    if(state.book&&options.updateScopeRoute!==false)setProductionScopeRoute(state.book.id,id,{replace:!!options.replaceScopeRoute});
    state.productionFlow={chapterId:id,selectedStepId:null,autoSelected:true};
    state.dialogInitialTab=options.initialTab||'reflowed';
    state.diffChapterId=null;state.diffRevisions=null;state.diffData=null;
    $('#dialogTitle').textContent=state.dialog.chapter.title;
    $('#qaIssues').innerHTML=state.dialog.qa_issues.slice(0,12).map(i=>`<div class="issue">${esc(i.message)}</div>`).join('');
    const box=$('#audioBox'),meta=$('#chapterAudioMeta');
    if(state.dialog.audio_artifact){
      const url=`/api/artifacts/${state.dialog.audio_artifact.id}/file`;
      box.classList.remove('hidden');$('#chapterAudio').src=url;$('#audioFileLink').href=url;
      const metaText=chapterAudioMetaText(state.dialog.active_output);
      meta.textContent=metaText;meta.classList.toggle('hidden',!metaText);
    }else{
      box.classList.add('hidden');$('#chapterAudio').removeAttribute('src');meta.textContent='';meta.classList.add('hidden');
    }
    renderProductionShell();
    if(state.dialogInitialTab==='casting'){
      await openCasting();
      if(state.casting){renderProductionShell();applyCastingOperatorSummary()}
    }
    else showRevision(state.dialogInitialTab);
    if(!options.skipProjectionReload)await loadProductionTaskProjection({silent:true});
    if(options.keepDialogClosed||state.dialogInitialTab==='casting'){if($('#textDialog').open)$('#textDialog').close()}
    else $('#textDialog').showModal();
  }catch(e){
    renderProductionShell(currentProductionViewModel({apiError:e.message}));
    toast(e.message,true);
  }
}
function showRevision(kind){document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===kind));$('#openCastingShortcut')?.classList.toggle('casting-tab-shortcut',kind==='casting');if(kind==='casting'){if($('#textDialog')?.open)$('#textDialog').close();setupProductionWorkspace();openCasting().then(()=>$('#productionPhaseWorkspace')?.scrollIntoView({block:'start',behavior:'smooth'}));return}if(kind==='diff'){openTextDiff();return}$('#castingPanel').classList.add('hidden');$('#textDiffPanel').classList.add('hidden');$('#chapterText').classList.remove('hidden');const rev=state.dialog?.revisions.find(r=>r.kind===kind)||state.dialog?.revisions.find(r=>r.kind==='reflowed');$('#chapterText').textContent=rev?.text||'Chưa có revision này.'}
