function castingVoiceOptions(selected=''){const items=voiceCatalogItems(),known=items.some(item=>item.assignment_key===selected),groups={preset:items.filter(item=>item.source_kind==='preset'),custom:items.filter(item=>item.source_kind==='custom')};let html='';if(!known&&selected)html+=`<option value="${esc(selected)}" selected data-legacy-voice="true">Legacy / unavailable: ${esc(selected)}</option>`;if(groups.preset.length>0){html+='<optgroup label="Preset voices">';html+=groups.preset.map(item=>`<option value="${esc(item.assignment_key)}" ${item.assignment_key===selected?'selected':''}>${esc(voiceOptionLabel(item))}</option>`).join('');html+='</optgroup>'}if(groups.custom.length>0){html+='<optgroup label="Custom voices">';html+=groups.custom.map(item=>{const disabled=!item.selectable&&item.assignment_key!==selected;const suffix=item.selectable?'':` · ${voiceUnavailableLabel(item)}`;return `<option value="${esc(item.assignment_key)}" ${item.assignment_key===selected?'selected':''} ${disabled?'disabled':''} data-source-kind="custom" data-custom-voice-id="${esc(item.custom_voice_id??'')}">${esc(voiceOptionLabel(item)+suffix)}</option>`}).join('');html+='</optgroup>'}return html}
