function selectedVoiceProvenance(voiceId){if(!voiceId)return 'Chưa chọn giọng.';const item=voiceCatalogItem(voiceId);if(!item)return `Đang giữ giá trị cũ: ${voiceId}. Hãy chọn giọng khác nếu cần sửa.`;if(item.source_kind==='preset')return `${item.display_name} · preset VieNeu.`;if(!item.selectable)return `${item.display_name} · ${voiceUnavailableLabel(item)} Giá trị cũ được giữ cho đến khi bạn chủ động lưu thay đổi.`;return `${item.display_name} · custom:${item.custom_voice_id} · revision ${item.effective_revision_number||'?'} · ${item.effective_revision_source||'effective'} · ${item.effective_synthesis_revision_id?'effective revision #'+item.effective_synthesis_revision_id:'revision chưa rõ'}.`}
function renderVoiceProvenance(id,voiceId){const el=$('#'+id);if(el)el.textContent=selectedVoiceProvenance(voiceId)}
function voiceCatalogState(voiceId){if(!voiceId)return{label:'Unresolved',kind:'missing',available:false,selectable:false,provenance:'Chưa có giọng hiệu lực.',blocked:true};const item=voiceCatalogItem(String(voiceId));if(!item)return{label:String(voiceId),kind:'legacy',available:false,selectable:false,provenance:`Legacy / unavailable: ${voiceId}. Giá trị được giữ nguyên cho đến khi operator chủ động thay đổi.`,blocked:true};if(item.source_kind==='preset')return{label:item.display_name,kind:'preset',available:true,selectable:item.selectable!==false,provenance:item.provenance_summary||`${item.display_name} · preset VieNeu.`,blocked:item.selectable===false};return{label:`${item.display_name} (Custom)`,kind:'custom',available:true,selectable:item.selectable!==false,provenance:selectedVoiceProvenance(voiceId),blocked:item.selectable===false}}
function voiceSelectableForSave(voiceId){const stateInfo=voiceCatalogState(voiceId);return !!voiceId&&stateInfo.available&&stateInfo.selectable&&!stateInfo.blocked}
function renderNewCharacterVoiceProvenance(){const el=$('#newCharacterVoiceProvenance');if(!el)return;if($('#newCharacterAssignment')?.value==='custom')el.textContent=selectedVoiceProvenance($('#newCharacterVoice')?.value);else el.textContent='Đang kế thừa giọng hiệu lực từ Book Voice Profile.'}
function resolutionText(r){if(!r)return 'Chưa có giọng hiệu lực — hãy tạo Book Voice Profile.';let voiceLabel=voiceLabelFromId(r.resolved_voice_id);const item=voiceCatalogItem(r.resolved_voice_id),provenance=item?.source_kind==='custom'&&item.effective_revision_number?` · Revision ${item.effective_revision_number}`:'';return `Giọng hiệu lực: ${voiceLabel}${provenance} · Resolved from: ${sourceLabels[r.resolution_source]||r.resolution_source}${r.needs_review?' · Cần kiểm tra':''}`}
function renderVoiceProfile(){const vp=state.casting.voice_profile||{},p=vp.profile,first=voiceCatalogItems().find(item=>item.selectable)?.assignment_key||state.voices?.[0]?.id||'';$('#voiceProfileEmpty').classList.toggle('hidden',!!p);$('#voiceProfileMeta').textContent=p?`Profile v${p.config_version} · ${new Date(p.updated_at).toLocaleString('vi-VN')}`:'Chưa cấu hình';$('#profileNarratorVoice').innerHTML=castingVoiceOptions(p?.narrator_voice_id||first);$('#profileMaleVoice').innerHTML=castingVoiceOptions(p?.male_dialogue_voice_id||first);$('#profileFemaleVoice').innerHTML=castingVoiceOptions(p?.female_dialogue_voice_id||first);$('#profileExplicitVoice').innerHTML=castingVoiceOptions(p?.unknown_voice_id||first);$('#profileUnknownFallback').value=p?.unknown_fallback||'narrator';profileFallbackChanged();renderProfileProvenance();const validation=vp.validation;const missing=[...(validation?.missing_preset_ids||[]),...(validation?.missing_voice_ids||[])];$('#profileValidation').textContent=validation&&!validation.valid?`Thiếu hoặc không dùng được: ${missing.join(', ')}. Hãy cập nhật profile trước khi tạo casting plan mới.`:p?'Profile hợp lệ. Cấu hình tái sử dụng chỉ áp dụng cho plan/job mới; snapshot cũ giữ nguyên.':'';$('#profileValidation').classList.toggle('error-text',!!validation&&!validation.valid);$('#saveVoiceProfile').textContent=p?'Lưu Voice Profile':'Tạo Voice Profile';document.querySelectorAll('[data-profile-preview]').forEach(b=>b.disabled=!profilePreviewVoiceId(b.dataset.profilePreview)||!!(validation&&!validation.valid))}
