function reviewFilterMatch(row){const filter=$('#speakerReviewFilter').value,decision=state.speakerReview.decisions[row.utterance_id],level=row.invalid_item?'invalid':row.suggestion?.confidence_level;if(filter==='all')return true;if(filter==='unreviewed')return !row.reviewed&&!decision;if(filter==='invalid')return !!row.invalid_item;if(filter==='needs_review')return !!row.suggestion?.needs_review||!!row.invalid_item;return level===filter}
function reviewRowElement(row){const s=row.suggestion,level=row.invalid_item?'invalid':s?.confidence_level||'invalid',current=row.current_assignment?speakerName(row.current_assignment.speaker_type,row.current_assignment.character_id):'None',suggestion=s?speakerName(s.speaker_type,s.character_id):'Unavailable',reason=s?.reason||row.invalid_item?.error_code||'No reason provided.',alternatives=(s?.alternatives||[]).map(item=>`${speakerName(item.speaker_type,item.character_id)} ${Math.round(item.confidence*100)}%`).join(' · ')||'None',root=document.createElement('div'),pending=!row.reviewed&&!state.speakerReview.decisions[row.utterance_id];root.className=`speaker-review-row${reviewFilterMatch(row)?'':' hidden-filter'}${row.reviewed?' reviewed':''}`;root.dataset.reviewRow=row.utterance_id;root.dataset.reviewPending=pending?'true':'false';const check=document.createElement('input');check.className='review-check';check.type='checkbox';check.dataset.reviewCheck=row.utterance_id;check.checked=!!state.speakerReview.selected?.[row.utterance_id];check.onchange=()=>setReviewSelection(row.utterance_id,check.checked);const seq=document.createElement('span');seq.className='utterance-seq';seq.textContent=row.sequence;const textBox=document.createElement('div'),id=document.createElement('strong'),text=document.createElement('p'),currentText=document.createElement('small'),reviewText=document.createElement('small');id.textContent=row.utterance_id;text.className='speaker-review-text';text.textContent=row.text;currentText.textContent=`Current: ${current}`;reviewText.textContent=row.human_review?`Reviewed: ${speakerName(row.human_review.speaker_type,row.human_review.character_id)}`:'Reviewed: no';textBox.append(id,text,currentText,reviewText);const suggestionBox=document.createElement('div'),suggestionName=document.createElement('strong'),confidence=document.createElement('span'),reasonText=document.createElement('span'),alternativesText=document.createElement('small');suggestionBox.className='speaker-review-suggestion';suggestionName.textContent=suggestion;confidence.className=`confidence-${level}`;confidence.textContent=`${level.toUpperCase()}${s?` · ${Math.round(s.confidence*100)}%`:''}`;reasonText.textContent=reason;alternativesText.textContent=`Alternatives: ${alternatives}`;suggestionBox.append(suggestionName,confidence,reasonText,alternativesText);const decisionBox=document.createElement('div'),label=document.createElement('label'),select=document.createElement('select'),save=document.createElement('button'),preview=document.createElement('button'),voice=document.createElement('span');decisionBox.className='speaker-review-decision';label.append('Review decision');select.dataset.reviewChoice=row.utterance_id;const selected=reviewChoiceValue(row,state.speakerReview.decisions[row.utterance_id]||row.human_review),choices=[['skip','Skip for now'],['narrator','Mark Narrator'],['unknown','Keep Unknown']];(state.speakerReview.draft.characters||[]).forEach(c=>choices.push([`character:${c.id}`,`Map to character: ${c.display_name}`]));choices.forEach(([value,name])=>select.add(new Option(name,value,false,value===selected)));select.onchange=()=>setSpeakerReviewChoice(row.utterance_id,select.value);label.append(select);save.className='secondary';save.textContent='Save row review';save.disabled=!runtimeAllowsMutation();save.onclick=()=>saveSpeakerReviewRow(row.utterance_id);preview.className='ghost';preview.textContent='Preview effective voice';preview.onclick=()=>previewReviewVoice(row.utterance_id);voice.id=`review-voice-${row.utterance_id}`;voice.className='review-voice-result';decisionBox.append(label,save,preview,voice);const details=document.createElement('details'),summary=document.createElement('summary'),contextList=document.createElement('div');details.className='speaker-context';summary.textContent='Context';contextList.className='speaker-context-list';(row.context||[]).forEach(item=>{const context=document.createElement('div');context.className=`speaker-context-item${item.is_target?' target':''}`;context.textContent=item.text;if(item.confirmed_assignment){const known=document.createElement('small');known.textContent=` · ${speakerName(item.confirmed_assignment.speaker_type,item.confirmed_assignment.character_id)}`;context.append(known)}contextList.append(context)});details.append(summary,contextList);root.append(check,seq,textBox,suggestionBox,decisionBox,details);return root}
function renderSpeakerReview(){const review=state.speakerReview||{},draft=review.draft,items=review.drafts||[],existingPlan=!!state.casting?.casting?.id;$('#speakerDraftSelect').innerHTML=items.length?items.map(item=>`<option value="${item.id}" ${draft?.id===item.id?'selected':''}>Draft #${item.id}${item.stale?' · Outdated':''} · ${esc(item.status||'invalid')}</option>`).join(''):'<option value="">Chưa có draft</option>';$('#speakerReviewEmpty').classList.toggle('hidden',items.length>0);$('#speakerReviewWorkspace').classList.toggle('hidden',!draft);$('#speakerReviewPanel').classList.toggle('has-existing-plan',existingPlan);$('#speakerDraftExistingPlanWarning').classList.toggle('hidden',!existingPlan);$('#approveSpeakerReview').textContent=speakerDraftApprovalLabel();$('#regenerateSpeakerDraft').disabled=!runtimeAllowsMutation()||!draft||review.busy;$('#generateSpeakerDraft').disabled=!runtimeAllowsMutation()||!!review.busy;$('#refreshSpeakerDrafts').disabled=!!review.busy;if(!draft){$('#speakerReviewStatus').textContent='Chưa có draft';$('#speakerReviewMeta').innerHTML='';$('#speakerReviewRows').replaceChildren();$('#speakerReviewStale').classList.add('hidden');$('#speakerReviewApprovalResult').textContent='';return}$('#speakerReviewStatus').textContent=draft.stale?'Draft đã cũ':`${draft.status} · còn ${localRemainingUnreviewedCount(review)} mục`;const counts={high:0,medium:0,low:0,invalid:0};draft.review_rows.forEach(row=>{counts[row.invalid_item?'invalid':row.suggestion?.confidence_level||'invalid']++});$('#speakerReviewMeta').innerHTML=`<div><strong>#${draft.id}</strong><span>Draft</span></div><div><strong>${esc(draft.model_id)}</strong><span>${esc(draft.prompt_version)}</span></div><div><strong>${draft.target_count} / ${draft.valid_count} / ${draft.invalid_count}</strong><span>Target / valid / invalid</span></div><div><strong>${counts.high} / ${counts.medium} / ${counts.low} / ${counts.invalid}</strong><span>High / medium / low / invalid</span></div><div><strong>${esc(draft.input_fingerprint.slice(0,12))}</strong><span>Input fingerprint</span></div><div><strong>#${draft.text_revision_id}</strong><span>Text revision</span></div>${review.generation?`<div><strong>${review.generation.reused?'Reused':'Generated'}</strong><span>Cache ${review.generation.cache?.hit_count||0} hit / ${review.generation.cache?.miss_count||0} miss</span></div>`:''}`;$('#speakerReviewStale').textContent=(draft.stale_reasons||[]).join(' ');$('#speakerReviewStale').classList.toggle('hidden',!draft.stale);$('#speakerReviewApprovalResult').textContent=review.lastApproval?`Đã tạo Final Voice Map draft v${review.lastApproval.casting_plan_revision}. Hãy chuyển sang phần Bản đồ giọng cuối để kiểm tra và duyệt riêng.`:'';const rows=draft.review_rows.map(reviewRowElement);if(rows.length)$('#speakerReviewRows').replaceChildren(...rows);else{const empty=document.createElement('p');empty.className='muted';empty.textContent='Draft này không có mục nào cần rà soát.';$('#speakerReviewRows').replaceChildren(empty)}updateSpeakerReviewApproval()}
async function loadSpeakerDrafts(preferredId=null){const review=state.speakerReview;review.busy=true;renderSpeakerReview();try{const data=await api(`/api/chapters/${review.chapterId}/speaker-assignment/drafts`);review.drafts=data.items;const usable=data.items.find(item=>item.id===+preferredId)||data.items.find(item=>!item.stale&&!item.load_error)||data.items[0];if(usable&&!usable.load_error){review.draft=await api(`/api/chapters/${review.chapterId}/speaker-assignment/drafts/${usable.id}`);review.decisions={};review.selected={}}else review.draft=null}finally{review.busy=false;renderSpeakerReview();renderProductionShell()}}
async function openSpeakerDraft(id){if(!id)return;try{state.speakerReview.draft=await api(`/api/chapters/${state.speakerReview.chapterId}/speaker-assignment/drafts/${id}`);state.speakerReview.decisions={};state.speakerReview.selected={};renderSpeakerReview()}catch(e){toast(e.message,true)}}
async function generateSpeakerDraft(force=false){if(!runtimeAllowsMutation()){toast('Runtime identity must be resolved before mutating actions.',true);return}const review=state.speakerReview,mode=force?'reanalyze':'unassigned_only',envelope=await runProductionCommand({commandType:'CREATE_SPEAKER_PROPOSAL',scope:chapterProductionCommandScope(review.chapterId),payload:{chapter_id:Number(review.chapterId),mode,utterance_ids:null,force_refresh:force},label:'Đang tạo đề xuất người nói…'}),item=envelope?.applied_items?.[0];if(item?.draft_id)await loadSpeakerDrafts(item.draft_id)}
function setSpeakerReviewChoice(utteranceId,value){const row=state.speakerReview.draft.review_rows.find(item=>item.utterance_id===utteranceId),decision=row?reviewDecision(row,value):null;if(decision)state.speakerReview.decisions[utteranceId]=decision;else delete state.speakerReview.decisions[utteranceId];updateSpeakerReviewApproval()}
function updateSpeakerReviewApproval(){const review=state.speakerReview,draft=review?.draft,count=reviewedDecisionCount(review),saved=(draft?.reviewed_utterance_ids||[]).length;$('#speakerReviewDecisionCount').textContent=`${saved} saved · ${count} pending · ${draft?.remaining_unreviewed_count??0} remaining`;$('#approveSpeakerReview').disabled=!runtimeAllowsMutation()||!draft||review.busy||!draftOnlyApprovalReady(review);const createPlan=$('#createSpeakerReviewCastingPlan');if(createPlan)createPlan.disabled=!runtimeAllowsMutation()||!draft||review.busy||!reviewReadyForCastingPlan(review);document.querySelectorAll('[data-review-row]').forEach(el=>{const row=draft.review_rows.find(item=>item.utterance_id===el.dataset.reviewRow);el.classList.toggle('hidden-filter',!reviewFilterMatch(row))})}
