function jumpToPendingReview(){const pending=[...document.querySelectorAll('[data-review-row][data-review-pending="true"]:not(.hidden-filter)')][0]||[...document.querySelectorAll('[data-review-row]:not(.hidden-filter)')][0];pending?.scrollIntoView({block:'center',behavior:'smooth'})}
