async function previewReviewVoice(utteranceId){const decision=state.speakerReview.decisions[utteranceId],target=$(`#review-voice-${CSS.escape(utteranceId)}`);if(!decision){target.textContent='Hãy chọn quyết định rà soát trước.';return}try{const result=await api(`/api/books/${state.casting.chapter.book_id}/voice-profile/resolve`,{method:'POST',body:JSON.stringify({speaker_type:decision.speaker_type==='narrator'?'narrator':'dialogue',character_id:decision.character_id})});target.textContent=`${result.resolved_voice_id} · ${sourceLabels[result.resolution_source]||result.resolution_source} · ${result.gender}${result.needs_review?' · Cần kiểm tra':''}`}catch(e){target.textContent=e.message}}
async function reviewIdempotencyKey(draft,decisions){const stable=JSON.stringify([...decisions].sort((a,b)=>a.utterance_id.localeCompare(b.utterance_id))),bytes=new TextEncoder().encode(stable),digest=await crypto.subtle.digest('SHA-256',bytes);return `review-${draft.id}-${[...new Uint8Array(digest)].map(value=>value.toString(16).padStart(2,'0')).join('').slice(0,32)}`}
function rowReviewPayload(decision){if(!decision)return null;if(decision.speaker_type==='narrator')return {decision:'MARK_NARRATOR'};if(decision.speaker_type==='unknown')return {decision:'KEEP_UNKNOWN'};if(decision.speaker_type==='character')return {decision:'MAP_TO_EXISTING_CHARACTER',character_id:decision.character_id};return null}
