function revisionLabel(r){return `${r.kind} · #${r.id} · ${r.char_count.toLocaleString('vi-VN')} ký tự · ${r.short_hash}`}
function latestRevision(kind){return [...(state.diffRevisions||[])].reverse().find(r=>r.kind===kind)}
function setDiffPreset(leftKind,rightKind){const left=latestRevision(leftKind),right=latestRevision(rightKind);if(!left||!right)return;$('#diffRevisionA').value=left.id;$('#diffRevisionB').value=right.id;loadTextDiff()}
async function openTextDiff(){try{$('#chapterText').classList.add('hidden');$('#castingPanel').classList.add('hidden');$('#textDiffPanel').classList.remove('hidden');if(state.diffChapterId===state.dialog.chapter.id&&state.diffRevisions){renderDiffSelectors();return}$('#diffContent').innerHTML='<p class="muted">Đang tải danh sách revision…</p>';const data=await api(`/api/chapters/${state.dialog.chapter.id}/revisions`);state.diffChapterId=state.dialog.chapter.id;state.diffRevisions=data.items;state.diffData=null;state.diffMode='inline';renderDiffSelectors();const preferred=latestRevision('reflowed')&&latestRevision('repaired')?['reflowed','repaired']:latestRevision('raw')&&latestRevision('reflowed')?['raw','reflowed']:null;if(preferred)setDiffPreset(...preferred);else $('#diffContent').innerHTML='<p class="muted">Chapter cần ít nhất hai revision để tạo diff.</p>'}catch(e){$('#diffContent').textContent=e.message;toast(e.message,true)}}
function renderDiffSelectors(){const options=(state.diffRevisions||[]).map(r=>`<option value="${r.id}">${esc(revisionLabel(r))}</option>`).join('');$('#diffRevisionA').innerHTML=options;$('#diffRevisionB').innerHTML=options;document.querySelectorAll('[data-diff-preset]').forEach(button=>{const [a,b]=button.dataset.diffPreset.split(',');const missing=[a,b].filter(kind=>!latestRevision(kind));button.disabled=missing.length>0;button.title=missing.length?`Thiếu revision: ${missing.join(', ')}`:''})}
async function loadTextDiff(){const a=+$('#diffRevisionA').value,b=+$('#diffRevisionB').value;if(!a||!b)return;$('#diffContent').innerHTML='<p class="muted">Đang tính diff…</p>';try{state.diffData=await api(`/api/chapters/${state.dialog.chapter.id}/diff?revision_a=${a}&revision_b=${b}`);renderTextDiff()}catch(e){state.diffData=null;$('#diffContent').innerHTML=`<div class="issue">${esc(e.message)}</div>`}}
function visibleDiffText(value,operation){if(operation.whitespace_only&&$('#diffShowWhitespace').checked)return esc(value.replace(/ /g,'·').replace(/\t/g,'→').replace(/\n/g,'↵\n'));return esc(value)}
function renderDiffOperation(operation,side){let value=side==='left'?operation.left:operation.right;if(!value)return '';if(operation.whitespace_only&&!$('#diffShowWhitespace').checked)return '';const isEqual=operation.status==='equal';if(isEqual&&!$('#diffShowUnchanged').checked&&value.length>220)value=`${value.slice(0,90)} … ${value.slice(-90)}`;let cls='diff-equal';if(side==='left'&&['delete','replace'].includes(operation.status))cls='diff-removed';if(side==='right'&&['insert','replace'].includes(operation.status))cls='diff-added';return `<span class="${cls}${operation.whitespace_only?' diff-whitespace':''}">${visibleDiffText(value,operation)}</span>`}
function renderInlineBlock(block){if(block.status==='equal'&&block.collapsed_by_default&&!$('#diffShowUnchanged').checked)return '<div class="diff-collapsed">… phần không đổi đã thu gọn …</div>';const body=block.operations.map(op=>{if(op.status==='equal')return renderDiffOperation(op,'right');return renderDiffOperation(op,'left')+renderDiffOperation(op,'right')}).join('');return `<div class="diff-block ${block.status}">${body}</div>`}
function renderSideBlock(block){if(block.status==='equal'&&block.collapsed_by_default&&!$('#diffShowUnchanged').checked)return '<div class="diff-collapsed">… phần không đổi đã thu gọn …</div>';const left=block.operations.map(op=>renderDiffOperation(op,'left')).join(''),right=block.operations.map(op=>renderDiffOperation(op,'right')).join('');return `<div class="diff-side-row ${block.status}"><div>${left}</div><div>${right}</div></div>`}
function renderTextDiff(){const d=state.diffData;if(!d)return;const s=d.summary,meta=r=>`<div><strong>${esc(r.kind)} #${r.id}</strong><span>${esc(r.created_at)} · parent ${r.parent_revision_id??'—'} · ${esc(r.processor_version)} · ${esc(r.short_hash)}</span><span>${esc(r.status)}${r.is_active?' · active':''}${r.is_raw_selected?' · raw selected':''}</span></div>`;$('#diffRevisionMeta').innerHTML=meta(d.revision_a)+meta(d.revision_b);$('#diffSummary').innerHTML=`<div><strong>${s.blocks_changed}</strong><span>block thay đổi</span></div><div><strong>+${s.tokens_added} / −${s.tokens_removed}</strong><span>lexical token</span></div><div><strong>${s.punctuation_changes}</strong><span>punctuation</span></div><div><strong>${(s.change_ratio*100).toFixed(2)}%</strong><span>tỷ lệ lexical change</span></div><div><strong>${s.characters_a.toLocaleString('vi-VN')}</strong><span>ký tự A</span></div><div><strong>${s.characters_b.toLocaleString('vi-VN')}</strong><span>ký tự B</span></div>`;$('#diffWarnings').innerHTML=[...d.warnings,...(!s.lexical_integrity&&s.lexical_reason?[s.lexical_reason]:[])].map(w=>`<div class="issue">${esc(w)}</div>`).join('');$('#diffInlineMode').classList.toggle('active',state.diffMode!=='side');$('#diffSideMode').classList.toggle('active',state.diffMode==='side');$('#diffContent').className=`diff-content ${state.diffMode==='side'?'side':''}`;$('#diffContent').innerHTML=d.blocks.map(block=>state.diffMode==='side'?renderSideBlock(block):renderInlineBlock(block)).join('')||'<p class="muted">Hai revision trống.</p>'}
function bytes(n){if(n===null||n===undefined)return '—';if(n<1024)return `${n} B`;if(n<1048576)return `${(n/1024).toFixed(1)} KB`;return `${(n/1048576).toFixed(1)} MB`}
function statusBadge(status){return `<span class="badge ${esc(status)}">${esc(fmtStatus(status))}</span>`}
function fileState(item){if(!item.file_exists)return '<span class="diag-bad">Thiếu file</span>';if(item.hash_matches===false)return '<span class="diag-bad">Sai hash</span>';return '<span class="diag-good">Hợp lệ</span>'}

async function loadJobs(){try{const jobs=await api('/api/jobs');const mutationAttr=runtimeAllowsMutation()?'':' data-runtime-mutation-control disabled title="Resolve runtime identity before mutating jobs"';$('#jobs').innerHTML=jobs.map(j=>{const done=j.actual_completed||0,total=j.total_chapters||0,pct=total?Math.round(done*100/total):100,badge=outputBadge(j),meta=jobOutputMeta(j);return `<div class="job-card"><div class="job-top"><div><div class="job-title">#${j.id} · ${esc(j.book_title)} · Chương ${j.from_chapter}–${j.to_chapter}</div><div class="job-meta">${esc(j.voice_name)} · ${esc(j.repair_mode)} · ${esc(j.output_format.toUpperCase())}${j.current_chapter_number?` · hiện tại chương ${j.current_chapter_number}`:''}</div>${meta?`<div class="job-output-meta">${esc(meta)}</div>`:''}</div><div>${statusBadge(j.status)}${badge}</div></div><div class="progress"><span style="width:${pct}%"></span></div><div class="job-meta">${done}/${total} chương · ${j.completed_segments||0}/${j.total_segments||0} segment${j.actual_failed?` · ${j.actual_failed} lỗi`:''}</div>${j.error_message?`<div class="issue">${esc(j.error_message)}</div>`:''}<div class="job-actions"><button onclick="openJobDiagnostics(${j.id})">Chẩn đoán</button>${['scheduled','queued','running','repairing','synthesizing','assembling'].includes(j.status)?`<button${mutationAttr} onclick="act(${j.id},'pause')">Tạm dừng</button><button${mutationAttr} onclick="act(${j.id},'cancel')">Hủy</button>`:''}${j.status==='paused'?`<button${mutationAttr} onclick="act(${j.id},'resume')">Tiếp tục</button><button${mutationAttr} onclick="act(${j.id},'cancel')">Hủy</button>`:''}${['completed_with_errors','failed'].includes(j.status)?`<button${mutationAttr} onclick="act(${j.id},'retry')">Thử lại phần lỗi</button>`:''}</div></div>`}).join('')||'<p class="muted">Chưa có job.</p>';syncMutationControls()}catch(e){console.error(e)}}
async function loadJobs(){try{const jobs=await api('/api/jobs');state.jobs=jobs;const mutationAttr=runtimeAllowsMutation()?'':' data-runtime-mutation-control disabled title="Resolve runtime identity before mutating jobs"';$('#jobs').innerHTML=jobs.map(j=>{const done=j.actual_completed||0,total=j.total_chapters||0,pct=total?Math.round(done*100/total):100,badge=outputBadge(j),meta=jobOutputMeta(j),preparedActions=j.status==='prepared'?`<button${mutationAttr} onclick="startPreparedJob(${j.id})">Bắt đầu render</button><button${mutationAttr} onclick="act(${j.id},'cancel')">Hủy</button>`:'';return `<div class="job-card"><div class="job-top"><div><div class="job-title">#${j.id} · ${esc(j.book_title)} · Chương ${j.from_chapter}–${j.to_chapter}</div><div class="job-meta">${esc(j.voice_name)} · ${esc(j.repair_mode)} · ${esc(j.output_format.toUpperCase())}${j.current_chapter_number?` · hiện tại chương ${j.current_chapter_number}`:''}</div>${meta?`<div class="job-output-meta">${esc(meta)}</div>`:''}</div><div>${statusBadge(j.status)}${badge}</div></div><div class="progress"><span style="width:${pct}%"></span></div><div class="job-meta">${done}/${total} chương · ${j.completed_segments||0}/${j.total_segments||0} segment${j.actual_failed?` · ${j.actual_failed} lỗi`:''}</div>${j.error_message?`<div class="issue">${esc(j.error_message)}</div>`:''}<div class="job-actions"><button onclick="openJobDiagnostics(${j.id})">Chẩn đoán</button>${preparedActions}${['scheduled','queued','running','repairing','synthesizing','assembling'].includes(j.status)?`<button${mutationAttr} onclick="act(${j.id},'pause')">Tạm dừng</button><button${mutationAttr} onclick="act(${j.id},'cancel')">Hủy</button>`:''}${j.status==='paused'?`<button${mutationAttr} onclick="act(${j.id},'resume')">Tiếp tục</button><button${mutationAttr} onclick="act(${j.id},'cancel')">Hủy</button>`:''}${['completed_with_errors','failed'].includes(j.status)?`<button${mutationAttr} onclick="act(${j.id},'retry')">Thử lại phần lỗi</button>`:''}</div></div>`}).join('')||'<p class="muted">Chưa có job.</p>';renderHomeSummary();syncMutationControls()}catch(e){console.error(e)}}
async function startPreparedJob(id){if(!runtimeAllowsMutation()){toast('Runtime identity must be resolved before mutating actions.',true);return}const envelope=await runProductionCommand({commandType:'START_RENDER',scope:jobProductionCommandScope(id),payload:{job_id:Number(id)},label:'Đang bắt đầu render…'});if(envelope){await loadJobs();if(state.dialog?.chapter)await openCasting()}}
function openCurrentCharacterVoices(chapterId){if(!chapterId)return;$('#jobDiagnosticsDialog').close();openChapter(chapterId,{initialTab:'casting'})}
async function openJobDiagnostics(id){try{const data=await api(`/api/diagnostics/jobs/${id}`);state.diagnosticJobId=id;$('#jobDiagnosticTitle').textContent=`Job #${id} · ${data.job.book_title}`;const counts=Object.entries(data.summary.chapter_status_counts).map(([s,n])=>`<span>${statusBadge(s)} ${n}</span>`).join('');const banner=data.job.is_active_output?'<div class="diag-job-banner">ACTIVE CHAPTER OUTPUT</div>':data.job.is_historical_output?'<div class="diag-job-banner historical">JOB LỊCH SỬ · không phải output hiện tại của chương</div>':'';$('#jobDiagnosticBody').innerHTML=`${banner}<div class="diag-summary"><div><strong>${data.summary.chapter_total}</strong><span>chương</span></div><div><strong>${data.summary.segment_verified}/${data.summary.segment_total}</strong><span>segment hợp lệ</span></div><div><strong>${data.summary.segment_failed}</strong><span>segment lỗi</span></div><div><strong>${data.summary.repair_failed}</strong><span>Gemini lỗi</span></div></div><div class="diag-line">${statusBadge(data.job.status)} <span>${counts}</span></div>${data.job.error_message?`<div class="issue">${esc(data.job.error_message)}</div>`:''}<h3>Chương</h3><div class="diag-table-wrap"><table class="diag-table"><thead><tr><th>Chương</th><th>Trạng thái</th><th>Gemini</th><th>Segment</th><th>Audio</th><th></th></tr></thead><tbody>${data.chapters.map(c=>`<tr><td>${c.chapter_number}. ${esc(c.title)}</td><td>${statusBadge(c.status)}${c.error_message?`<small>${esc(c.error_message)}</small>`:''}</td><td>${c.repair_failed}/${c.repair_total} lỗi</td><td>${c.segment_verified}/${c.segment_total}${c.segment_failed?` · ${c.segment_failed} lỗi`:''}</td><td>${c.is_active_output?'ACTIVE AUDIO':c.artifact_active?'Historical':'?'}</td><td class="diag-actions"><button onclick="openChapterDiagnostics(${c.job_chapter_id})">Chi tiết</button><button class="linklike" onclick="openCurrentCharacterVoices(${c.chapter_id})">Mở quy trình Sản xuất hiện tại</button>${['failed','needs_review','cancelled','interrupted'].includes(c.status)?`<button onclick="retryChapter(${c.job_chapter_id})">Thử lại</button>`:''}</td></tr>`).join('')}</tbody></table></div><details><summary>Cấu hình snapshot</summary><pre class="diag-json">${esc(JSON.stringify(data.job.settings,null,2))}</pre></details><details><summary>Nhật ký gần đây (${data.events.length})</summary><div class="event-list">${data.events.map(e=>`<div><code>${esc(e.event_code)}</code><span>${esc(e.created_at)}</span></div>`).join('')||'Chưa có sự kiện.'}</div></details>`;$('#chapterDiagnosticsDialog').close();$('#segmentDiagnosticsDialog').close();if(!$('#jobDiagnosticsDialog').open)$('#jobDiagnosticsDialog').showModal()}catch(e){toast(e.message,true)}}
async function openChapterDiagnostics(id){try{const data=await api(`/api/diagnostics/job-chapters/${id}`);state.diagnosticChapterId=id;state.diagnosticJobId=data.chapter.job_id;$('#chapterDiagnosticTitle').textContent=`Chương ${data.chapter.chapter_number} · ${data.chapter.title}`;const rev=data.text_revision;$('#chapterDiagnosticBody').innerHTML=`<div class="diag-line">${statusBadge(data.chapter.status)}${rev?`<span>Revision #${rev.id} · ${esc(rev.kind)} · ${rev.char_count.toLocaleString('vi-VN')} ký tự</span>`:'<span>Chưa gắn text revision</span>'}</div>${data.chapter.error_message?`<div class="issue">${esc(data.chapter.error_message)}</div>`:''}<h3>Gemini repair blocks (${data.repair_blocks.length})</h3>${data.repair_blocks.length?`<div class="diag-table-wrap"><table class="diag-table"><thead><tr><th>#</th><th>Trạng thái</th><th>Lần thử</th><th>Source</th><th>Output</th><th>Lỗi</th></tr></thead><tbody>${data.repair_blocks.map(b=>`<tr><td>${b.block_index}</td><td>${statusBadge(b.status)}</td><td>${b.attempt_count}</td><td>${b.source_file_exists?'Có':'Thiếu'}</td><td>${b.repaired_file_exists?'Có':'?'}</td><td>${esc(b.error_message||'')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Không dùng Gemini repair cho chương này.</p>'}<h3>Segments (${data.segments.length})</h3><div class="diag-table-wrap"><table class="diag-table"><thead><tr><th>#</th><th>Trạng thái</th><th>Text</th><th>Audio</th><th>Thời lượng</th><th></th></tr></thead><tbody>${data.segments.map(s=>`<tr><td>${s.segment_index}</td><td>${statusBadge(s.status)}${s.error_message?`<small>${esc(s.error_message)}</small>`:''}</td><td class="diag-preview">${esc(s.text_preview||'?')}</td><td>${fileState(s)} · ${bytes(s.actual_size_bytes)}</td><td>${s.duration_ms?`${(s.duration_ms/1000).toFixed(1)}s`:'?'}</td><td class="diag-actions"><button onclick="openSegmentDiagnostics(${s.id})">Chi tiết</button>${['failed','interrupted'].includes(s.status)?`<button onclick="retrySegmentAction(${s.id})">Thử lại</button>`:''}</td></tr>`).join('')}</tbody></table></div><h3>Artifacts (${data.artifacts.length})</h3>${data.artifacts.length?`<div class="diag-table-wrap"><table class="diag-table"><thead><tr><th>Loại</th><th>Trạng thái</th><th>File</th><th>Kích thước</th></tr></thead><tbody>${data.artifacts.map(a=>`<tr><td>${esc(a.artifact_type)}</td><td>${statusBadge(a.status)}</td><td>${fileState(a)} · ${esc(a.filename||'?')}</td><td>${bytes(a.actual_size_bytes)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Chưa có artifact.</p>'}`;$('#jobDiagnosticsDialog').close();$('#segmentDiagnosticsDialog').close();if(!$('#chapterDiagnosticsDialog').open)$('#chapterDiagnosticsDialog').showModal()}catch(e){toast(e.message,true)}}
async function openSegmentDiagnostics(id){try{const s=await api(`/api/diagnostics/segments/${id}`);state.diagnosticSegmentId=id;state.diagnosticChapterId=s.job_chapter_id;$('#segmentDiagnosticTitle').textContent=`Segment #${s.segment_index} · Chương ${s.chapter_number}`;$('#segmentDiagnosticBody').innerHTML=`<div class="diag-line">${statusBadge(s.status)}<span>Lần thử: ${s.attempt_count}</span><span>Thời lượng: ${s.duration_ms?`${(s.duration_ms/1000).toFixed(2)}s`:'?'}</span></div>${s.error_message?`<div class="issue">${esc(s.error_message)}</div>`:''}<h3>Text đầu vào</h3><pre class="segment-text">${esc(s.text_preview||'Không đọc được text blob.')}</pre><div class="file-grid"><div><strong>Text blob</strong>${fileState(s.text_file)}<span>${bytes(s.text_file.actual_size_bytes)}</span></div><div><strong>WAV segment</strong>${fileState(s.audio_file)}<span>${bytes(s.audio_file.actual_size_bytes)}</span></div></div><div class="diag-actions">${['failed','interrupted'].includes(s.status)?`<button class="primary" onclick="retrySegmentAction(${s.id})">Thử lại segment này</button>`:''}${s.status==='verified'?`<button ${runtimeAllowsMutation()?'':regenerateMutationAttr} onclick="regenerateSegment(${s.id})">${regenerateButtonLabel}</button>`:''}</div><div id="segmentAttemptsContainer"></div>`;$('#chapterDiagnosticsDialog').close();if(!$('#segmentDiagnosticsDialog').open)$('#segmentDiagnosticsDialog').showModal();if(s.status==='verified')refreshSegmentAttempts(s.id)}catch(e){toast(e.message,true)}}
async function retryChapter(id){if(!runtimeAllowsMutation()){toast('Runtime identity must be resolved before mutating actions.',true);return}const jobId=Number(state.diagnosticJobId||0);if(!jobId){toast('Không tìm thấy Job cho chương cần thử lại.',true);return}const envelope=await runProductionCommand({commandType:'RETRY_JOB_CHAPTER',scope:jobProductionCommandScope(jobId),payload:{job_id:jobId,job_chapter_id:Number(id)},label:'Đang xếp lại chương lỗi…'});if(envelope){$('#chapterDiagnosticsDialog').close();await loadJobs();await openJobDiagnostics(jobId)}}
async function retrySegmentAction(id){if(!runtimeAllowsMutation()){toast('Runtime identity must be resolved before mutating actions.',true);return}const jobId=Number(state.diagnosticJobId||0);if(!jobId){toast('Không tìm thấy Job cho segment cần thử lại.',true);return}const envelope=await runProductionCommand({commandType:'RETRY_SEGMENT',scope:jobProductionCommandScope(jobId),payload:{job_id:jobId,segment_id:Number(id)},label:'Đang xếp lại segment lỗi…'});if(envelope){$('#segmentDiagnosticsDialog').close();await loadJobs();await openJobDiagnostics(jobId)}}

window.openJobDiagnostics=openJobDiagnostics;window.openChapterDiagnostics=openChapterDiagnostics;window.openSegmentDiagnostics=openSegmentDiagnostics;window.retryChapter=retryChapter;window.retrySegmentAction=retrySegmentAction;window.openCurrentCharacterVoices=openCurrentCharacterVoices;

// Segment Regeneration UI
const regenerateMutationAttr='data-runtime-mutation-control disabled title="Resolve runtime identity before regenerating"';
// status==='verified' gates the regenerate control in the diagnostics UI contract.
const regenerateEligibleStatus='verified';
const regenerateButtonLabel='Regenerate Verified Segment';
const retryableSegmentStatuses=['failed','interrupted'];
async function regenerateSegment(segmentId) {
  if(!runtimeAllowsMutation()){toast('Runtime identity must be resolved before mutating actions.',true);return}
  const jobId=Number(state.diagnosticJobId||0);
  if(!jobId){toast('Không tìm thấy Job cho segment cần tạo lại.',true);return}
  const envelope=await runProductionCommand({commandType:'REGENERATE_SEGMENT',scope:jobProductionCommandScope(jobId),payload:{job_id:jobId,segment_id:Number(segmentId)},label:'Đang tạo candidate mới…'});
  const item=envelope?.applied_items?.[0];
  if(item){state.segmentCandidate={segmentId,attemptId:item.attempt_id,attemptNumber:item.attempt_number};await refreshSegmentAttempts(segmentId)}
}

async function refreshSegmentAttempts(segmentId) {
  try {
    const data = await api(`/api/segments/${segmentId}/attempts`);
    state.segmentAttempts = data;
    renderSegmentAttempts(segmentId);
    await refreshAudioRepairBlocks(state.diagnosticChapterId);
  } catch(e) {
    toast(e.message, true);
  }
}

async function refreshAudioRepairBlocks(jobChapterId) {
  if (!jobChapterId) return;
  try {
    const data = await api(`/api/job-chapters/${jobChapterId}/repair-blocks`);
    state.audioRepairBlocks = data;
    renderAudioRepairBlocks();
  } catch(e) {
    state.audioRepairBlocks = null;
  }
}

function renderSegmentAttempts(segmentId) {
  const data = state.segmentAttempts;
  if (!data) return;

  const container = $('#segmentAttemptsContainer');
  if (!container) return;

  let html = '<h3>Segment Attempts</h3><div class="attempts-grid">';

  if (data.active_attempt) {
    html += `<div class="attempt-card active"><strong>Active (Attempt ${data.active_attempt.attempt_number})</strong>`;
    html += `<span>${(data.active_attempt.duration_ms/1000).toFixed(2)}s</span>`;
    html += `<audio controls src="/api/segments/${segmentId}/audio"></audio>`;
    if (regenerateEligibleStatus==='verified' && !data.candidate) {
      html += `<div class="attempt-actions"><button class="secondary" ${runtimeAllowsMutation()?'':regenerateMutationAttr} onclick="regenerateSegment(${segmentId})">${regenerateButtonLabel}</button></div>`;
    }
    html += `</div>`;
  }

  if (data.candidate) {
    html += `<div class="attempt-card candidate"><strong>Candidate (Attempt ${data.candidate.attempt_number})</strong>`;
    html += `<span>${(data.candidate.duration_ms/1000).toFixed(2)}s</span>`;
    html += `<audio controls src="/api/segment-attempts/${data.candidate.attempt_id}/audio"></audio>`;
    html += `<div class="attempt-actions">`;
    html += `<button class="primary" onclick="acceptCandidate(${segmentId}, ${data.candidate.attempt_id})">Accept</button>`;
    html += `<button class="ghost" onclick="rejectCandidate(${segmentId}, ${data.candidate.attempt_id})">Reject</button>`;
    html += `</div></div>`;
  }

  if (data.history && data.history.length > 0) {
    html += '<details><summary>History</summary>';
    data.history.forEach(h => {
      html += `<div class="attempt-card history"><span>Attempt ${h.attempt_number} (${h.status})</span>`;
      html += `<span>${(h.duration_ms/1000).toFixed(2)}s</span></div>`;
    });
    html += '</details>';
  }

  html += '</div>';
  html += '<div id="audioRepairBlocksContainer"></div>';
  container.innerHTML = html;
  renderAudioRepairBlocks();
}

function renderAudioRepairBlocks() {
  const container = $('#audioRepairBlocksContainer');
  if (!container) return;
  const blocks = state.audioRepairBlocks?.repair_blocks || [];
  if (!blocks.length) {
    container.innerHTML = '<h3>Audio Repair Blocks</h3><p class="muted">No adjacent-segment repair candidate.</p>';
    return;
  }
  let html = '<h3>Audio Repair Blocks</h3><div class="attempts-grid">';
  blocks.forEach(block => {
    html += `<div class="attempt-card ${block.status==='candidate'?'candidate':'history'}">`;
    html += `<strong>Repair Block #${block.id} (${esc(block.status)})</strong>`;
    html += `<span>Segments ${block.first_segment_id}-${block.last_segment_id}; ${(block.candidate_duration_ms/1000).toFixed(2)}s</span>`;
    html += `<pre class="segment-text">${esc(block.source_text || '')}</pre>`;
    html += '<label class="muted">Original active range</label>';
    html += `<audio controls src="/api/audio-repair-blocks/${block.id}/active-audio"></audio>`;
    html += '<label class="muted">Repair-block candidate</label>';
    html += `<audio controls src="/api/audio-repair-blocks/${block.id}/audio"></audio>`;
    if (block.status === 'candidate') {
      html += '<div class="attempt-actions">';
      html += `<button class="primary" onclick="acceptRepairBlock(${block.id})">Accept</button>`;
      html += `<button class="ghost" onclick="rejectRepairBlock(${block.id})">Reject</button>`;
      html += '</div>';
    }
    html += '</div>';
  });
  html += '</div>';
  container.innerHTML = html;
}

async function createRepairBlock(jobId, firstSegmentId, lastSegmentId) {
  if(!runtimeAllowsMutation()){toast('Runtime identity must be resolved before mutating actions.',true);return}
  const envelope=await runProductionCommand({commandType:'CREATE_AUDIO_REPAIR_BLOCK',scope:jobProductionCommandScope(jobId),payload:{job_id:Number(jobId),first_segment_id:Number(firstSegmentId),last_segment_id:Number(lastSegmentId)},label:'Đang tạo repair-block candidate…'});
  const item=envelope?.applied_items?.[0];
  if(item?.job_chapter_id)await refreshAudioRepairBlocks(item.job_chapter_id);
}

async function rejectRepairBlock(repairBlockId) {
  const jobId=Number(state.diagnosticJobId||0);
  if(!jobId){toast('Không tìm thấy Job cho repair block.',true);return}
  const envelope=await runProductionCommand({commandType:'REJECT_AUDIO_REPAIR_BLOCK',scope:jobProductionCommandScope(jobId),payload:{job_id:jobId,repair_block_id:Number(repairBlockId)},label:'Đang loại repair-block candidate…'});
  if(envelope)await refreshAudioRepairBlocks(state.diagnosticChapterId);
}

async function acceptRepairBlock(repairBlockId) {
  if (!confirm('Accept this repair block? This will reassemble the chapter artifact without TTS.')) return;
  const jobId=Number(state.diagnosticJobId||0);
  if(!jobId){toast('Không tìm thấy Job cho repair block.',true);return}
  const envelope=await runProductionCommand({commandType:'ACCEPT_AUDIO_REPAIR_BLOCK',scope:jobProductionCommandScope(jobId),payload:{job_id:jobId,repair_block_id:Number(repairBlockId)},label:'Đang chấp nhận repair block…'});
  const item=envelope?.applied_items?.[0];
  if(item?.job_chapter_id)await refreshAudioRepairBlocks(item.job_chapter_id);
}

async function acceptCandidate(segmentId, attemptId) {
  if (!confirm('Accept this candidate? This will rebuild the chapter artifact.')) return;
  const jobId=Number(state.diagnosticJobId||0);
  if(!jobId){toast('Không tìm thấy Job cho candidate.',true);return}
  const envelope=await runProductionCommand({commandType:'ACCEPT_SEGMENT_CANDIDATE',scope:jobProductionCommandScope(jobId),payload:{job_id:jobId,segment_id:Number(segmentId),attempt_id:Number(attemptId)},label:'Đang chấp nhận candidate…'});
  if(envelope){state.segmentCandidate=null;await refreshSegmentAttempts(segmentId)}
}

async function rejectCandidate(segmentId, attemptId) {
  const jobId=Number(state.diagnosticJobId||0);
  if(!jobId){toast('Không tìm thấy Job cho candidate.',true);return}
  const envelope=await runProductionCommand({commandType:'REJECT_SEGMENT_CANDIDATE',scope:jobProductionCommandScope(jobId),payload:{job_id:jobId,segment_id:Number(segmentId),attempt_id:Number(attemptId)},label:'Đang loại candidate…'});
  if(envelope){state.segmentCandidate=null;await refreshSegmentAttempts(segmentId)}
}

