function clearRegistryDraft(speakerKey){if(!state.bookVoiceRegistry.drafts&&!state.bookVoiceRegistry.rowErrors)return;state.bookVoiceRegistry.drafts={...(state.bookVoiceRegistry.drafts||{})};state.bookVoiceRegistry.rowErrors={...(state.bookVoiceRegistry.rowErrors||{})};delete state.bookVoiceRegistry.drafts[speakerKey];delete state.bookVoiceRegistry.rowErrors[speakerKey]}
