function rememberRegistryDraft(speakerKey){if(!speakerKey)return;const existing=state.bookVoiceRegistry.drafts?.[speakerKey]||{},voice=registryControlByKey('data-registry-voice-key',speakerKey)?.value||existing.voice||'',scope=registryControlByKey('data-registry-scope-key',speakerKey)?.value||existing.scope||'',characterId=registryControlByKey('data-registry-character-key',speakerKey)?.value||existing.characterId||'',newCharacter=registryControlByKey('data-registry-new-character',speakerKey)?.value||existing.newCharacter||'',alias=registryControlByKey('data-registry-alias-key',speakerKey)?.value||existing.alias||'';state.bookVoiceRegistry.drafts={...(state.bookVoiceRegistry.drafts||{}),[speakerKey]:{voice,scope,characterId,newCharacter,alias}};if(state.bookVoiceRegistry.rowErrors?.[speakerKey]){state.bookVoiceRegistry.rowErrors={...state.bookVoiceRegistry.rowErrors};delete state.bookVoiceRegistry.rowErrors[speakerKey]}}
async function saveRegistrySpeakerMapping(speakerKey){
  if(!runtimeAllowsMutation()){toast('Runtime identity must be resolved before mutating actions.',true);return}
  const row=registryRowByKey(speakerKey),context=currentProductionWorkingContext();if(!row||!context)return;
  rememberRegistryDraft(speakerKey);
  const draft=registryDraftForKey(speakerKey),alias=(draft.alias||'').trim(),aliases=alias?[alias]:[];
  let characterId=Number(draft.characterId||0);
  state.bookVoiceRegistry.savingKey=speakerKey;renderAssignmentPage();
  try{
    if(!characterId){
      const name=(draft.newCharacter||'').trim();
      if(!name){setRegistryRowError(speakerKey,'Hãy nhập tên nhân vật mới hoặc chọn nhân vật có sẵn.');return}
      const created=await runProductionCommand({commandType:'CREATE_CHARACTER',scope:rangeProductionCommandScope(),payload:{book_id:context.bookId,display_name:name,aliases,gender:'unknown',role:'unknown'},label:'Đang tạo nhân vật…'});
      const item=created?.applied_items?.[0];
      characterId=Number(item?.character_id||0);
      if(!characterId){setRegistryRowError(speakerKey,'Chưa tạo được nhân vật để gán. Có thể thử lại an toàn.');return}
    }
    const envelope=await runProductionCommand({commandType:'MAP_SPEAKER_TO_CHARACTER',scope:rangeProductionCommandScope(),payload:{book_id:context.bookId,speaker_key:speakerKey,character_id:characterId,aliases,expected_registry_fingerprint:registryRowFingerprint(row)},label:'Đang gán người nói với nhân vật…'});
    if(envelope?.outcome==='APPLIED'||envelope?.outcome==='PARTIAL'){clearRegistryDraft(speakerKey);await loadBookVoiceRegistry({force:true});await loadProductionTaskProjection({silent:true})}
    else setRegistryRowError(speakerKey,state.productionCommand.message||'Chưa gán được nhân vật. Có thể thử lại an toàn.')
  }finally{state.bookVoiceRegistry.savingKey=null;renderAssignmentPage()}
}
async function createTopLevelAssignmentCharacter(){
  if(!runtimeAllowsMutation()){toast('Runtime identity must be resolved before mutating actions.',true);return}
  const context=currentProductionWorkingContext();if(!context)return;
  const name=prompt('Tên nhân vật mới:');
  if(!name||!name.trim())return;
  const envelope=await runProductionCommand({commandType:'CREATE_CHARACTER',scope:rangeProductionCommandScope(),payload:{book_id:context.bookId,display_name:name.trim(),aliases:[],gender:'unknown',role:'unknown'},label:'Đang tạo nhân vật…'});
  if(envelope?.outcome==='APPLIED'||envelope?.outcome==='PARTIAL')await loadBookVoiceRegistry({force:true})
}
