function renderAssignmentPage(){
  const scope=$('#assignmentScope'),summary=$('#assignmentSummary'),rowsRoot=$('#assignmentRows'),blocked=$('#assignmentBlockedReason'),button=$('#openAssignmentWorkspace'),returnButton=$('#assignmentReturnToRepair');if(!scope||!summary||!rowsRoot)return;
  rowsRoot.dataset.assignmentTools='bulk narrator/unknown';
  const workingContext=currentProductionWorkingContext();if(workingContext){renderBookVoiceRegistryPage(workingContext,state.bookVoiceRegistry);return}
  const chapter=state.dialog?.chapter,context=state.casting,repairContext=state.assignmentContext?.sourceTask==='REPAIR_REQUIRED';
  if(returnButton)returnButton.classList.toggle('hidden',!repairContext);
  if(assignmentContextLoading){
    scope.textContent='Đang mở đúng chương để gán giọng.';summary.innerHTML='';rowsRoot.innerHTML='<div class="assignment-empty-state"><strong>Đang tải ngữ cảnh chương</strong><span>Hệ thống đang lấy chapter, bản đồ giọng và catalog giọng đã lưu.</span></div>';blocked.textContent='Chưa có thay đổi nào được thực hiện.';blocked.classList.remove('hidden');if(button){button.disabled=true;button.textContent='Đang tải'}return
  }
  if(!chapter||!context){
    scope.textContent='Chưa chọn sách và chương.';summary.innerHTML='';rowsRoot.innerHTML='<div class="assignment-empty-state"><strong>Chọn đúng chương trước khi gán giọng</strong><span>Bộ chọn dùng cùng phạm vi canonical của Sản xuất và không tạo dữ liệu.</span></div>';blocked.textContent='Chưa có thay đổi nào được thực hiện.';blocked.classList.remove('hidden');if(button){button.disabled=false;button.textContent='Chọn sách và chương'}return
  }
  const rows=buildSpeakerSummaryRows(context),plan=context.casting||{},readiness=buildSpeakerReadinessSummary(rows),counts=assignmentLineCounts(context),profile=context.voice_profile||{},narrator=profile.narrator_resolution||{},editable=repairContext&&plan.status!=='draft';
  scope.textContent=`${state.book?.title||chapter.book_title||'Sách'} · Chương ${chapter.chapter_number} · Text Revision ${chapter.active_text_revision_id||'—'}`;
  summary.innerHTML=`<div><strong>${rows.length}</strong><span>người nói</span></div><div><strong>${readiness.needsReview}</strong><span>cần kiểm tra</span></div><div><strong>${plan.status==='approved'?'Đã duyệt':plan.status==='draft'?'Bản nháp':'Chưa có'}</strong><span>bản đồ giọng</span></div><div><strong>${state.voiceCatalog?.items?.filter(item=>item.selectable).length||0}</strong><span>giọng khả dụng</span></div>`;
  const narratorControl=editable?`<select data-assignment-voice="narrator" aria-label="Giọng người kể chuyện">${castingVoiceOptions(narrator.resolved_voice_id||'')}</select>`:`<strong>${esc(voiceLabelFromId(narrator.resolved_voice_id)||'Chưa gán')}</strong>`;
  const characterRows=(context.characters||[]).map(character=>{const resolution=character.effective_resolution||{},count=counts[`character:${character.id}`]||0,control=editable?`<select data-assignment-voice="character:${character.id}" aria-label="Giọng cho ${esc(character.display_name)}">${castingVoiceOptions(resolution.resolved_voice_id||'')}</select>`:`<strong>${esc(voiceLabelFromId(resolution.resolved_voice_id)||'Chưa gán')}</strong>`;return `<div class="assignment-voice-row"><div><strong>${esc(character.display_name)}</strong><span>${esc(operatorRoleLabel(character.role,character.gender||resolution.gender||'unknown'))} · ${count} câu</span></div><div>${control}<span>${esc(assignmentResolutionSource(resolution))} · ${resolution.available===false?'Không khả dụng':'Khả dụng'}</span></div></div>`}).join('');
  rowsRoot.innerHTML=`<div class="assignment-voice-row"><div><strong>Người kể chuyện</strong><span>${counts.narrator||0} câu</span></div><div>${narratorControl}<span>${esc(assignmentResolutionSource(narrator))} · ${narrator.available===false?'Không khả dụng':'Khả dụng'}</span></div></div>${characterRows||'<p class="muted">Chương này chưa có nhân vật riêng.</p>'}`;
  blocked.classList.toggle('hidden',readiness.needsReview===0);blocked.textContent=readiness.needsReview?`${readiness.needsReview} người nói chưa có giọng an toàn. Hãy chọn giọng khả dụng trước khi tạo bản nháp mới.`:'';
  if(button){button.disabled=false;button.textContent=plan.status==='draft'?'Duyệt bản đồ giọng mới':editable?'Lưu giọng và tạo bản nháp':'Mở chỉnh giọng trong Sản xuất'}
}
async function saveAssignmentVoiceChanges(){
  const context=state.casting,chapter=state.dialog?.chapter,profile={...(context?.voice_profile?.profile||{})},narrator=$('[data-assignment-voice="narrator"]')?.value||profile.narrator_voice_id;if(!context||!chapter||!narrator)return;
  const assignments=[...document.querySelectorAll('[data-assignment-voice^="character:"]')].map(select=>{const character_id=Number(select.dataset.assignmentVoice.split(':')[1]),character=context.characters.find(item=>Number(item.id)===character_id);return{character_id,gender:character?.gender||'unknown',voice_override_id:select.value||null}});
  const payload={book_id:Number(chapter.book_id),profile:{narrator_voice_id:narrator,male_dialogue_voice_id:profile.male_dialogue_voice_id||narrator,female_dialogue_voice_id:profile.female_dialogue_voice_id||narrator,unknown_fallback:profile.unknown_fallback||'narrator',unknown_voice_id:profile.unknown_voice_id||null},assignments};
  const saved=await runProductionCommand({commandType:'SAVE_VOICE_ASSIGNMENTS',scope:chapterProductionCommandScope(chapter.id),payload,label:'Đang lưu giọng cho chương…'});
  if(saved?.outcome!=='APPLIED'&&saved?.outcome!=='PARTIAL')return;
  await openCasting();await saveCastingDraft();renderAssignmentPage()
}
async function approveAssignmentRepairPlan(){const envelope=await approveCastingPlan();if(envelope?.outcome==='APPLIED'){setAppRoute('production');if(state.assignmentContext?.returnHash)history.replaceState(null,'',state.assignmentContext.returnHash);await loadProductionTaskProjection()}}
async function openAssignmentWorkspace(){
  const chapter=state.dialog?.chapter,plan=state.casting?.casting||{};
  if(!chapter){setAppRoute('assignment');openProductionScopeDialog();return}
  if(state.assignmentContext?.sourceTask==='REPAIR_REQUIRED'){
    if(plan.status==='draft'){await approveAssignmentRepairPlan();return}
    if($('[data-assignment-voice]')){await saveAssignmentVoiceChanges();return}
  }
  setAppRoute('production');setProductionScopeRoute(state.book?.id||chapter.book_id,chapter.id,{replace:true});await focusProductionTarget(currentProductionViewModel().targetPanel)
}
function returnFromAssignmentToRepair(){const context=state.assignmentContext;if(context?.returnHash)history.replaceState(null,'',context.returnHash);setAppRoute('production');loadProductionTaskProjection()}

function safeJobSummary(job){return [`Job #${job.id}`,`${job.book_title||'Book'} ${job.from_chapter}-${job.to_chapter}`,`status=${job.status}`,`chapters=${job.actual_completed||0}/${job.total_chapters||0}`,`segments verified=${job.completed_segments||0} failed=${job.failed_segments||0} pending=${job.pending_segments||0}`,job.error_classification?`error=${job.error_classification}`:''].filter(Boolean).join(' | ')}
function renderJobsPage(){const root=$('#jobsPageList'),status=$('#jobsPageStatus');if(!root||!status)return;const jobs=state.jobs||[];status.textContent=`${jobs.length} Job gần nhất. Tự động cập nhật mỗi 2.5 giây.`;root.innerHTML=jobs.map(job=>{const actions=job.actions||{},progress=`${job.actual_completed||0}/${job.total_chapters||0} chapter; ${job.completed_segments||0} verified, ${job.failed_segments||0} failed, ${job.pending_segments||0} pending segment`,voice=[job.voice_name,...(job.active_output_chapters||[]).map(row=>row.active_output_casting_plan_revision?`Plan v${row.active_output_casting_plan_revision}`:'')].filter(Boolean).join(' / ');return `<article class="job-page-card ${job.is_historical_output?'historical':''}"><div class="job-page-head"><div><p class="eyebrow">Job #${job.id}</p><h3>${esc(job.book_title)} / ${job.from_chapter}-${job.to_chapter}</h3></div>${statusBadge(job.status)}${outputBadge(job)}</div><div class="job-page-grid"><div><strong>Progress</strong><span>${esc(progress)}</span></div><div><strong>Applied voices</strong><span>${esc(voice||'Pinned in Job snapshot')}</span></div><div><strong>Created</strong><span>${esc(job.created_at||'—')}</span></div><div><strong>Updated</strong><span>${esc(job.updated_at||'—')}</span></div><div><strong>Error class</strong><span>${esc(job.error_classification||'none')}</span></div></div>${job.error_message?`<div class="issue warning">${esc(job.error_message)}</div>`:''}<div class="job-actions"><button type="button" onclick="openJobDiagnostics(${job.id})">Mở chi tiết</button><button type="button" onclick="copyJobSummary(${job.id})">Copy tóm tắt an toàn</button>${actions.can_start?`<button class="primary" type="button" onclick="startPreparedJob(${job.id})">START_RENDER Job #${job.id}</button>`:''}${actions.can_resume?`<button type="button" onclick="act(${job.id},'resume')">Tiếp tục</button>`:''}${actions.can_retry?`<button type="button" onclick="act(${job.id},'retry')">Thử lại phần recoverable</button>`:''}${actions.can_open_audio?`<button type="button" onclick="openJobAudio(${job.id})">Mở audio</button>`:''}</div>${job.is_historical_output?'<p class="muted">Historical evidence only. Không có action render/retry.</p>':''}</article>`}).join('')||'<p class="muted">Chưa có Job.</p>'}
async function copyJobSummary(jobId){const job=(state.jobs||[]).find(item=>Number(item.id)===Number(jobId));if(!job)return;try{await navigator.clipboard.writeText(safeJobSummary(job));toast('Da copy tom tat Job an toan.')}catch{toast(safeJobSummary(job))}}
async function openJobAudio(jobId){const job=(state.jobs||[]).find(item=>Number(item.id)===Number(jobId)),artifactId=job?.active_output_chapters?.[0]?.active_audio_artifact_id;if(!artifactId)return;setAppRoute('audio');await loadAudioLibrary({force:true});const item=state.audioLibrary.items.find(row=>Number(row.artifact_id)===Number(artifactId));if(item)selectAudioLibraryItem(item,{play:false})}

const renderAudioLibraryCore=renderAudioLibrary;
renderAudioLibrary=function(){renderAudioLibraryCore();renderAudioRangeState();renderAudioQaPanel()};
const renderAudioLibraryItemCore=renderAudioLibraryItem;
renderAudioLibraryItem=function(item){const card=renderAudioLibraryItemCore(item),main=card.querySelector('.audio-library-card-main'),selector=document.createElement('label'),checkbox=document.createElement('input');selector.className='audio-range-selector';checkbox.type='checkbox';checkbox.checked=state.audioArchive.selectedChapterIds.includes(Number(item.chapter_id));checkbox.setAttribute('aria-label',`Chọn Chapter ${item.chapter_number} cho ZIP range`);checkbox.addEventListener('change',()=>toggleAudioRangeChapter(item,checkbox.checked));selector.append(checkbox,document.createTextNode(' Chọn cho ZIP'));main?.appendChild(selector);return card};
const selectAudioLibraryItemCore=selectAudioLibraryItem;
selectAudioLibraryItem=function(item,options={}){const changed=Number(state.audioLibrary.selectedArtifactId)!==Number(item.artifact_id);selectAudioLibraryItemCore(item,options);renderAudioQaPanel(item);if(changed||!state.audioQa.history.length)loadAudioQaHistory(item.chapter_id)};
function selectedAudioLibraryItem(){return state.audioLibrary.items.find(item=>Number(item.artifact_id)===Number(state.audioLibrary.selectedArtifactId))||null}
function renderAudioQaPanel(item=selectedAudioLibraryItem()){const panel=$('#audioLibraryQaPanel');if(!panel)return;if(!item){panel.classList.add('hidden');return}panel.classList.remove('hidden');$('#audioQaIdentity').textContent=`Chapter ${item.chapter_number} / Job #${item.job_id||'?'} / Artifact #${item.artifact_id} / ${formatDurationMs(item.duration_ms)} / ${bytes(item.size_bytes)}`;$('#audioQaVoiceSummary').textContent=`Requested voice: ${item.requested_voice||'Job snapshot'} / Applied narrator: ${item.applied_narrator_voice||'Casting Plan snapshot'} / Plan ${item.casting_plan_revision?`v${item.casting_plan_revision}`:'unknown'}.`;const history=$('#audioQaHistory');history.innerHTML=state.audioQa.loading?'Đang tải...':state.audioQa.history.map(row=>`<div class="qa-history-row"><strong>${row.status==='approved'?'Accepted':'Needs fixes'}</strong><span>${esc(row.recorded_at||'')}</span><p>${esc(row.notes||'Không có ghi chú')}</p><small>Job #${row.job_id||'?'} / Artifact #${row.artifact_id||'?'}</small></div>`).join('')||'Chưa có lịch sử QA.'}
async function loadAudioQaHistory(chapterId){state.audioQa.loading=true;state.audioQa.history=[];renderAudioQaPanel();try{const data=await api(`/api/chapters/${chapterId}/human-approval-history`);state.audioQa.history=data.items||[]}catch(e){toast(e.message,true)}finally{state.audioQa.loading=false;renderAudioQaPanel()}}
async function submitAudioQa(status){const item=selectedAudioLibraryItem();if(!item)return;const notes=$('#audioQaNote').value.trim();if(status==='needs_fixes'&&!notes){toast('Cần nhập ghi chú trước khi chọn Needs fixes.',true);$('#audioQaNote').focus();return}const label=status==='approved'?'Accept':'Needs fixes';if(!window.confirm(`${label} Artifact #${item.artifact_id} của Chapter ${item.chapter_number}?`))return;const commandType=status==='approved'?'HUMAN_QA_ACCEPT':'HUMAN_QA_NEEDS_FIXES',envelope=await runProductionCommand({commandType,scope:artifactProductionCommandScope(item.artifact_id),payload:{chapter_id:Number(item.chapter_id),notes},label:'Đang ghi kết quả QA…'});if(envelope?.outcome==='APPLIED'){const artifactId=item.artifact_id;await loadAudioLibrary({force:true});const refreshed=state.audioLibrary.items.find(row=>Number(row.artifact_id)===Number(artifactId));if(refreshed)selectAudioLibraryItem(refreshed,{play:false});$('#audioQaNote').value=''}}
function toggleAudioRangeChapter(item,selected){const id=Number(item.chapter_id),set=new Set(state.audioArchive.selectedChapterIds);if(selected)set.add(id);else set.delete(id);state.audioArchive.selectedChapterIds=[...set];state.audioArchive.readiness=null;renderAudioRangeState()}
function selectedAudioRangeItems(){const ids=new Set(state.audioArchive.selectedChapterIds);return state.audioLibrary.items.filter(item=>ids.has(Number(item.chapter_id))).sort((a,b)=>a.chapter_number-b.chapter_number)}
function audioRangeScope(){const items=selectedAudioRangeItems();if(!items.length)return{valid:false,message:'Chưa chọn chapter.'};const bookIds=new Set(items.map(item=>Number(item.book_id)));if(bookIds.size!==1)return{valid:false,message:'ZIP range chỉ được chọn trong một sách.'};for(let index=1;index<items.length;index+=1){if(Number(items[index].chapter_number)!==Number(items[index-1].chapter_number)+1)return{valid:false,message:'Các chapter đã chọn không liên tiếp.'}}return{valid:true,book_id:Number(items[0].book_id),from_chapter:Number(items[0].chapter_number),to_chapter:Number(items.at(-1).chapter_number),items}}
function renderAudioRangeState(){const scope=audioRangeScope(),summary=$('#audioRangeSummary'),issues=$('#audioRangeIssues'),download=$('#downloadAudioRange');if(!summary||!issues||!download)return;const ready=state.audioArchive.readiness;summary.textContent=scope.valid?`${scope.items.length} chapter: ${scope.from_chapter}-${scope.to_chapter}${ready?` / ${bytes(ready.estimated_size_bytes)}`:''}`:scope.message;const issueRows=ready?.issues||[];issues.classList.toggle('hidden',scope.valid&&issueRows.length===0);issues.innerHTML=!scope.valid?esc(scope.message):issueRows.map(row=>`<div>Chapter ${row.chapter_number}: ${esc(row.message)}</div>`).join('');download.disabled=!(scope.valid&&ready?.ready)}
async function checkAudioRange(){const scope=audioRangeScope();state.audioArchive.readiness=null;renderAudioRangeState();if(!scope.valid)return;state.audioArchive.loading=true;try{const params=new URLSearchParams({book_id:scope.book_id,from_chapter:scope.from_chapter,to_chapter:scope.to_chapter});state.audioArchive.readiness=await api(`/api/audio-library/range-archive-readiness?${params}`)}catch(e){toast(e.message,true)}finally{state.audioArchive.loading=false;renderAudioRangeState()}}
function downloadAudioRange(){const scope=audioRangeScope();if(!scope.valid||!state.audioArchive.readiness?.ready)return;const params=new URLSearchParams({book_id:scope.book_id,from_chapter:scope.from_chapter,to_chapter:scope.to_chapter}),link=document.createElement('a');link.href=`/api/audio-library/range-archive?${params}`;link.download=state.audioArchive.readiness.archive_name||'';document.body.appendChild(link);link.click();link.remove()}

function renderStorageReport(){const report=state.storage.report,summary=$('#storageSummary'),blockers=$('#storageBlockers'),candidates=$('#storageCandidates'),execute=$('#storageExecute'),reason=$('#storageActionReason'),last=$('#storageLastResult');if(!summary)return;if(state.storage.loading){summary.innerHTML='<p class="muted">Đang quét storage; dữ liệu lớn có thể mất hơn một phút...</p>';execute.disabled=true;reason.textContent='Vui lòng đợi báo cáo hoàn tất trước khi xác nhận cleanup.';return}if(!report){summary.innerHTML='<p class="muted">Chưa tải báo cáo.</p>';execute.disabled=true;return}summary.innerHTML=`<div><strong>${bytes(report.storage?.output_bytes||0)}</strong><span>Canonical output</span></div><div><strong>${bytes(report.storage?.reclaimable_bytes||0)}</strong><span>Proven orphan reclaimable</span></div><div><strong>${bytes(Math.max(0,(report.storage?.repository_bytes||0)-(report.storage?.reclaimable_bytes||0)))}</strong><span>Protected / retained</span></div><div><strong>${report.candidates?.length||0}</strong><span>Cleanup candidates</span></div>`;const blocked=report.blockers||[];blockers.classList.toggle('hidden',blocked.length===0);blockers.innerHTML=blocked.map(item=>`<div>${esc(item)}</div>`).join('');candidates.innerHTML=(report.candidates||[]).map(item=>`<div class="storage-candidate"><strong>${esc(item.category)}</strong><span>${esc(item.path)} / ${bytes(item.bytes)}</span><small>${esc(item.reason)}</small></div>`).join('')||'<p class="muted">Không có proven orphan candidate.</p>';const exact=$('#storageConfirmation')?.value.trim()===report.cleanup_confirmation,canExecute=runtimeAllowsMutation()&&!blocked.length&&!!report.candidates?.length&&exact;execute.disabled=!canExecute;reason.textContent=blocked.length?'Cleanup bị chặn bởi safety check.':!report.candidates?.length?'Không có proven orphan cần xóa.':!exact?`Nhập chính xác ${report.cleanup_confirmation} để mở Execute.`:'Chỉ candidate trong báo cáo vừa tải sẽ được tái kiểm tra và xóa.';last.textContent=report.last_cleanup_result?`Lần cleanup gần nhất: ${report.last_cleanup_result.executed_at}; reclaimed ${bytes(report.last_cleanup_result.reclaimed_bytes)}.`:'Chưa có cleanup result.'}
async function loadStorageReport({dryRun=false}={}){state.storage.loading=true;renderStorageReport();try{state.storage.report=await api(dryRun?'/api/storage/dry-run':'/api/storage/report',dryRun?{method:'POST',body:'{}'}:{});state.storage.error=null;if(dryRun)toast('Dry run hoàn tất; không xóa file.')}catch(e){state.storage.error=e.message;toast(e.message,true)}finally{state.storage.loading=false;renderStorageReport()}}
function ensureStorageReportLoaded(){if(!state.storage.report&&!state.storage.loading)loadStorageReport()}
async function executeStorageCleanup(){const report=state.storage.report,confirmation=$('#storageConfirmation').value.trim();if(!report||confirmation!==report.cleanup_confirmation)return;if(!window.confirm(`Xóa ${report.candidates.length} proven orphan candidate, ước tính ${bytes(report.storage.reclaimable_bytes)}? Canonical Artifact sẽ được bảo vệ.`))return;try{const result=await api('/api/storage/cleanup',{method:'POST',body:JSON.stringify({confirmation})});toast(`Cleanup hoàn tất: reclaimed ${bytes(result.reclaimed_bytes)}.`);$('#storageConfirmation').value='';await loadStorageReport()}catch(e){toast(e.message,true)}}

function outputBadge(job){if(job.is_active_output)return '<span class="badge active-output">ACTIVE OUTPUT</span>';if(job.is_historical_output)return '<span class="badge historical">HISTORICAL</span>';return ''}
function jobOutputMeta(job){if(job.is_active_output&&job.active_output_chapters?.length){const chapter=job.active_output_chapters[0],plan=chapter.active_output_casting_plan_revision?` | Plan v${chapter.active_output_casting_plan_revision}`:'';return `Active chapter output: ${chapter.chapter_number}. ${chapter.chapter_title}${plan}`}if(job.is_historical_output)return 'Historical evidence only - not the current chapter output';return ''}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const loadJobsForProductionState=loadJobs;
loadJobs=async function(){await loadJobsForProductionState();await loadProductionTaskProjection({silent:true});renderProductionShell();renderJobsPage();renderAssignmentPage();renderGlobalStatus();renderHomeDashboard()}
